import React from "react";
import { Link } from "react-router-dom";
import heroImage from "../images/hero.jpg";

const Home = () => {
  return (
    <div
      style={{
        minHeight: "100vh",
        background: "#f8f4f6",
        padding: "30px",
        fontFamily: "Poppins, sans-serif",
      }}
    >
      <div
        style={{
          maxWidth: "1200px",
          margin: "auto",
          borderRadius: "40px",
          overflow: "hidden",
          position: "relative",
          boxShadow: "0 20px 60px rgba(0,0,0,0.15)",
        }}
      >
        {/* Background Image */}
        <div
          style={{
            backgroundImage: `url(${heroImage})`,
            backgroundSize: "cover",
            backgroundPosition: "center",
            height: "600px",
            position: "relative",
          }}
        >
          {/* Light Overlay */}
          <div
            style={{
              position: "absolute",
              inset: 0,
              background: "rgba(255,255,255,0.55)",
            }}
          ></div>

          {/* Center Content */}
          <div
            style={{
              position: "relative",
              zIndex: 2,
              height: "100%",
              display: "flex",
              flexDirection: "column",
              justifyContent: "center",
              alignItems: "center",
              textAlign: "center",
            }}
          >
            <h1
              style={{
                fontSize: "55px",
                color: "#d96b95",
                fontWeight: "700",
                marginBottom: "20px",
              }}
            >
              Nanhe Farishte <br /> Kiran Knits
            </h1>

            <p
              style={{
                fontSize: "20px",
                color: "#555",
                marginBottom: "35px",
              }}
            >
              Har bunai mein maa ka pyaar 💗
            </p>

            <Link to="/products">
              <button
                style={{
                  backgroundColor: "#ff7aa8",
                  border: "none",
                  padding: "15px 40px",
                  borderRadius: "50px",
                  color: "white",
                  fontSize: "18px",
                  fontWeight: "600",
                  cursor: "pointer",
                  boxShadow: "0 10px 25px rgba(0,0,0,0.2)",
                  transition: "0.3s",
                }}
                onMouseOver={(e) =>
                  (e.target.style.transform = "scale(1.08)")
                }
                onMouseOut={(e) =>
                  (e.target.style.transform = "scale(1)")
                }
              >
                ▶ Shop Now
              </button>
            </Link>
          </div>
        </div>
      </div>
    </div>
  );
};

export default Home;
